lor:#5d7153!important;font:500 9px/1.6 'KingHwaOldSong',sans-serif!important;letter-spacing:.12em!important}.xt-card:has(.xt-text-songTitle){padding-top:148px!important;background:#24331d!important;border-top:0!important}.xt-card:has(.xt-text-songTitle):before{content:'';position:absolute;left:0;right:0;top:0;height:148px;background-image:linear-gradient(180deg,rgba(41,65,30,.025),rgba(41,65,30,.24)),url('https://i.postimg.cc/vTN65bqH/1787489741669.png');background-size:cover;background-position:center 47%;filter:saturate(.86) contrast(.96)}.xt-card:has(.xt-text-songTitle) .xt-card-title{position:absolute!important;left:13px;top:11px;padding:0!important;color:#fff!important;text-shadow:0 2px 10px rgba(35,53,27,.42)!important}.xt-text-songTitle{padding:17px 100px 2px 16px!important;color:#f5f7ee!important;font:500 19px/1.45 'Noto Serif SC',serif!important;letter-spacing:.03em!important}.xt-text-songArtist{padding:0 100px 15px 16px!important;color:#bbc9ae!important;font:500 10px/1.5 'KingHwaOldSong',sans-serif!important;letter-spacing:.1em!important}.xt-text-listeningNote{margin:0 16px 18px!important;padding:13px 0 0!important;border-top:1px solid rgba(236,244,227,.28)!important;color:#dce6d4!important;font:400 12px/1.75 'KingHwaOldSong',sans-serif!important}.xt-text-listeningNote:after{content:'';position:absolute;right:0;top:-1px;width:27%;height:1px;background:#f3f6e9}.xt-footer{margin:13px 0 0!important;padding:12px 0 0!important;border-top:1px solid rgba(38,49,33,.88)!important;color:#607456!important;font:500 8px/1.4 'KingHwaOldSong',sans-serif!important;letter-spacing:.18em!important;text-align:right!important}.xt-particles,.xt-divider,.xt-badge{display:none!important}@keyframes magazine-open{from{opacity:.01;clip-path:inset(0 0 8% 0)}to{opacity:1;clip-path:inset(0)}}@media(max-width:420px){.xt-content{padding:48px 12px 14px!important}.xt-content:before{left:12px!important}.xt-content:after{right:12px!important;font-size:7px!important}.xt-card:has(.xt-text-innerVoice){padding-top:132px!important}.xt-card:has(.xt-text-innerVoice):before{height:132px!important}.xt-card:has(.xt-text-innerVoice):after{top:98px!important;font-size:22px!important}.xt-card:has(.xt-text-innerVoice) .xt-header{top:91px!important}.xt-text-innerVoice{font-size:17px!important;padding:22px 14px 23px!important}.xt-card:has(.xt-text-theatreOpening){padding-right:clamp(108px,22%,134px)!important}.xt-card:has(.xt-text-theatreOpening):after{width:clamp(92px,18%,118px)!important}.xt-text-theatreOpening,.xt-text-theatreDialogue,.xt-text-theatreEnding{font-size:12.5px!important}.xt-card:has(.xt-text-workQuote){min-height:220px!important;padding-right:39%!important}.xt-card:has(.xt-text-workQuote):before{width:38%!important}.xt-text-workQuote{font-size:17px!important;padding-left:11px!important}.xt-text-songTitle{padding-right:72px!important}.xt-text-songArtist{padding-right:72px!important}}@media(max-width:340px){.xt-card:has(.xt-text-theatreOpening){padding-right:clamp(108px,22%,134px)!important}.xt-card:has(.xt-text-theatreOpening):after{right:0!important;top:35px!important;bottom:14px!important;width:clamp(92px,18%,118px)!important}.xt-card:has(.xt-text-workQuote){padding-right:0!important;padding-top:122px!important}.xt-card:has(.xt-text-workQuote):before{left:0!important;right:0!important;top:0!important;width:100%!important;height:122px!important;background-position:center 48%!important}}@media(prefers-reduced-motion:reduce){.xt-content{animation:none!important}}
