_theme.customCss:
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; background: transparent !important; border-radius: 0 !important; }

/* ═══ 全局白底 ═══ */
.xt-root {
    position: relative !important;
    width: 100% !important; max-width: 420px !important;
    height: 780px !important;
    margin: 0 auto !important;
    background: #ffffff !important; /* 纯白底色 */
    color: #0f1419 !important; /* 深黑灰主文本 */
    font-family: -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif !important;
    overflow-y: auto !important; overflow-x: hidden !important;
    scrollbar-width: none !important;
    padding: 52px 0 20px 0 !important;
}
.xt-root::-webkit-scrollbar { display: none !important; }

/* ═══ 顶部导航 ═══ */
.xt-text:nth-of-type(2) {
    position: fixed !important; top: 0 !important; left: 50% !important;
    transform: translateX(-50%) !important;
    width: 100% !important; max-width: 420px !important;
    height: 52px !important; line-height: 52px !important;
    text-align: center !important;
    color: #0f1419 !important; font-size: 18px !important;
    font-weight: 800 !important; letter-spacing: 2px !important;
    background: rgba(255,255,255,0.95) !important; z-index: 99 !important;
    backdrop-filter: blur(10px) !important;
}
.xt-text:nth-of-type(1) {
    position: fixed !important; top: 0 !important;
    left: calc(50% - 180px) !important;
    width: 52px !important; height: 52px !important;
    z-index: 100 !important;
    color: transparent !important; font-size: 0 !important;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%230f1419' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><line x1='19' y1='12' x2='5' y2='12'/><polyline points='12 19 5 12 12 5'/></svg>") !important;
    background-size: 22px !important; background-repeat: no-repeat !important;
    background-position: 14px center !important;
}
.xt-text:nth-of-type(3) {
    position: fixed !important; top: 10px !important;
    left: calc(50% + 134px) !important;
    width: 32px !important; height: 32px !important;
    z-index: 101 !important;
    color: transparent !important; font-size: 0 !important;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%230f1419'><circle cx='5' cy='12' r='2'/><circle cx='12' cy='12' r='2'/><circle cx='19' cy='12' r='2'/></svg>") !important;
    background-size: 20px !important; background-repeat: no-repeat !important;
    background-position: center !important;
}

/* ═══ 主推文 ═══ */
.xt-text:nth-of-type(4) {
    float: left !important;
    margin: -4px 12px 0 16px !important;
    width: 44px !important; height: 44px !important;
    background-image: url('https://s3.bmp.ovh/2026/07/23/GvqFhJ2B.jpg') !important;
    background-color: #eff3f4 !important;
    background-size: cover !important; background-position: center !important;
    border-radius: 50% !important;
}
.xt-text:nth-of-type(5) { margin: 18px 90px 0 72px !important; color: #0f1419 !important; font-size: 15px !important; font-weight: 700 !important; line-height: 1.3 !important; }
.xt-text:nth-of-type(6) { margin: 2px 90px 0 72px !important; color: #536471 !important; font-size: 14px !important; line-height: 1.3 !important; }
.xt-text:nth-of-type(7) {
    position: absolute !important; top: 70px !important; right: 16px !important;
    padding: 4px 10px !important;
    background: #0f1419 !important; color: #ffffff !important;
    font-size: 11px !important; font-weight: 700 !important;
    border-radius: 999px !important; z-index: 5 !important;
}
.xt-text:nth-of-type(8) { clear: both !important; margin: 14px 16px 0 16px !important; padding-top: 4px !important; color: #0f1419 !important; font-size: 17px !important; line-height: 1.5 !important; }
.xt-text:nth-of-type(9) { float: left !important; margin: 16px 0 0 16px !important; color: #536471 !important; font-size: 14px !important; white-space: nowrap !important; }
.xt-text:nth-of-type(10) { float: left !important; margin: 16px 16px 0 0 !important; color: #536471 !important; font-size: 14px !important; white-space: nowrap !important; }
.xt-text:nth-of-type(10)::before { content: ' · ' !important; margin: 0 2px !important; }

/* 图标 */
.xt-text:nth-of-type(11),.xt-text:nth-of-type(12),.xt-text:nth-of-type(13),.xt-text:nth-of-type(14),.xt-text:nth-of-type(15) {
    float: left !important; width: 20% !important; height: 45px !important;
    color: #536471 !important; font-size: 15px !important; line-height: 20px !important;
    background-repeat: no-repeat !important; background-size: 22px !important;
    text-align: left !important; margin-top: 12px !important;
}
.xt-text:nth-of-type(11) { clear: both !important; background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23536471' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z'/></svg>") !important; background-position: 22px center !important; padding-left: 50px !important; padding-top: 12px !important; padding-bottom: 12px !important; }
.xt-text:nth-of-type(12) { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23536471' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polyline points='17 1 21 5 17 9'/><path d='M3 11V9a4 4 0 0 1 4-4h14'/><polyline points='7 23 3 19 7 15'/><path d='M21 13v2a4 4 0 0 1-4 4H3'/></svg>") !important; background-position: 27px center !important; padding-left: 56px !important; padding-top: 12px !important; padding-bottom: 12px !important; }
.xt-text:nth-of-type(13) { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23536471' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z'/></svg>") !important; background-position: 20px center !important; padding-left: 45px !important; padding-top: 12px !important; padding-bottom: 12px !important; }
.xt-text:nth-of-type(14) { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23536471' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><line x1='18' y1='20' x2='18' y2='10'/><line x1='12' y1='20' x2='12' y2='4'/><line x1='6' y1='20' x2='6' y2='14'/></svg>") !important; background-position: 20px center !important; padding-left: 45px !important; padding-top: 12px !important; padding-bottom: 12px !important; }
.xt-text:nth-of-type(15) { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23536471' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8'/><polyline points='16 6 12 2 8 6'/><line x1='12' y1='2' x2='12' y2='15'/></svg>") !important; background-position: 22px center !important; padding-left: 34px !important; padding-top: 12px !important; padding-bottom: 12px !important; }

/* 相关 · 查看引用 */
.xt-text:nth-of-type(16) {
    clear: both !important; float: left !important;
    padding: 14px 0 14px 16px !important;
    color: #0f1419 !important; font-size: 15px !important;
    font-weight: 600 !important;
    border-bottom: 1px solid #eff3f4 !important;
    width: 50% !important;
}
